describe('Form Submission Error Scrolling', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should scroll to form submission errors when validation fails', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/submit-form').as('formSubmit');

    // Fill in form with invalid data
    cy.get('[data-testid="name-input"]').type('John');
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="password-input"]').type('password123');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API call
    cy.wait('@formSubmit');

    // Verify error messages are displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please enter a valid email address');

    // Verify the page has scrolled to the error message
    cy.get('[data-testid="error-message"]').then(($error) => {
      const errorRect = $error[0].getBoundingClientRect();
      const viewportHeight = cy.get('body').then(($body) => $body[0].clientHeight);
      const errorTop = errorRect.top + cy.window().scrollLeft();

      // Assert that the error message is within the viewport or near the top
      expect(errorTop).to.be.lessThan(viewportHeight * 0.8);
    });

    // Verify the form is still visible
    cy.get('[data-testid="form-container"]').should('be.visible');
  });

  it('should not scroll when form is submitted successfully', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/submit-form', {
      statusCode: 200,
      body: { success: true, message: 'Form submitted successfully' }
    }).as('formSubmitSuccess');

    // Fill in form with valid data
    cy.get('[data-testid="name-input"]').type('Jane Doe');
    cy.get('[data-testid="email-input"]').type('jane@example.com');
    cy.get('[data-testid="password-input"]').type('password123');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the successful API call
    cy.wait('@formSubmitSuccess');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');

    // Verify no error message is displayed
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify the page has not scrolled to an error state
    cy.get('body').then(($body) => {
      const scrollPosition = $body[0].scrollTop;
      // Assert scroll position is within a reasonable range (not at the bottom of a long page)
      expect(scrollPosition).to.be.lessThan(500);
    });
  });
});
